#include <vector>
#include <algorithm>
#include <climits>
#include <cmath>
using namespace std;

class Solution {
public:
    int minOperationsToEqualize(vector<int>& nums, int k) {
        int n = nums.size();
        int ans = INT_MAX;
        for (int i = 0; i <= n - k; i++) {
            vector<int> window(nums.begin() + i, nums.begin() + i + k);
            sort(window.begin(), window.end());
            int med = window[k / 2];
            int cost = 0;
            for (int x : window) cost += abs(x - med);
            ans = min(ans, cost);
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int minOperationsToEqualize(int[] nums, int k) {
        int n = nums.length;
        int ans = Integer.MAX_VALUE;
        for (int i = 0; i <= n - k; i++) {
            int[] window = Arrays.copyOfRange(nums, i, i + k);
            Arrays.sort(window);
            int med = window[k / 2];
            int cost = 0;
            for (int x : window) cost += Math.abs(x - med);
            ans = Math.min(ans, cost);
        }
        return ans;
    }
}

var minOperationsToEqualize = function(nums, k) {
    let ans = Infinity;
    for (let i = 0; i <= nums.length - k; i++) {
        const window = nums.slice(i, i + k).sort((a, b) => a - b);
        const med = window[Math.floor(k / 2)];
        let cost = 0;
        for (const x of window) cost += Math.abs(x - med);
        ans = Math.min(ans, cost);
    }
    return ans;
};
